# Lua lexer
import re

KEYWORDS = {
    'and','break','do','else','elseif','end','false','for','function','goto',
    'if','in','local','nil','not','or','repeat','return','then','true','until',
    'while'
}

class Token:
    __slots__ = ('type','value','line')
    def __init__(self, type, value, line):
        self.type = type
        self.value = value
        self.line = line
    def __repr__(self):
        return f"Token({self.type!r},{self.value!r},{self.line})"

class LexError(Exception):
    def __init__(self, msg, line):
        super().__init__(msg)
        self.line = line

def _read_long_bracket(src, i, line):
    # src[i] == '['; count '=' then expect '['
    level = 0
    j = i + 1
    while j < len(src) and src[j] == '=':
        level += 1
        j += 1
    if j >= len(src) or src[j] != '[':
        return None
    j += 1
    # skip first newline
    if j < len(src) and src[j] == '\r':
        j += 1
        if j < len(src) and src[j] == '\n':
            j += 1
        line += 1
    elif j < len(src) and src[j] == '\n':
        j += 1
        line += 1
    close = ']' + '=' * level + ']'
    k = src.find(close, j)
    if k < 0:
        raise LexError("unterminated long string/comment", line)
    content = src[j:k]
    new_line = line + content.count('\n')
    return content, k + len(close), new_line

def _read_string(src, i, quote, line):
    # src[i] == quote
    i += 1
    out = []
    start_line = line
    while i < len(src):
        c = src[i]
        if c == quote:
            return ''.join(out), i + 1, line
        if c == '\n' or c == '\r':
            raise LexError("unterminated string", start_line)
        if c == '\\':
            i += 1
            if i >= len(src):
                raise LexError("unterminated string", start_line)
            esc = src[i]
            if esc == 'a': out.append('\a'); i += 1
            elif esc == 'b': out.append('\b'); i += 1
            elif esc == 'f': out.append('\f'); i += 1
            elif esc == 'n': out.append('\n'); i += 1
            elif esc == 'r': out.append('\r'); i += 1
            elif esc == 't': out.append('\t'); i += 1
            elif esc == 'v': out.append('\v'); i += 1
            elif esc == '\\': out.append('\\'); i += 1
            elif esc == '"': out.append('"'); i += 1
            elif esc == "'": out.append("'"); i += 1
            elif esc == '\n':
                out.append('\n'); i += 1; line += 1
            elif esc == '\r':
                out.append('\n'); i += 1
                if i < len(src) and src[i] == '\n':
                    i += 1
                line += 1
            elif esc == 'x':
                i += 1
                if i + 2 > len(src):
                    raise LexError("hexadecimal digit expected", line)
                h = src[i:i+2]
                if len(h) < 2 or not all(ch in '0123456789abcdefABCDEF' for ch in h):
                    raise LexError("hexadecimal digit expected", line)
                out.append(chr(int(h,16)))
                i += 2
            elif esc == 'z':
                i += 1
                while i < len(src) and src[i] in ' \t\n\r\v\f':
                    if src[i] == '\n':
                        line += 1
                    i += 1
            elif esc.isdigit():
                j = i
                while j < len(src) and j < i + 3 and src[j].isdigit():
                    j += 1
                n = int(src[i:j])
                if n > 255:
                    raise LexError("decimal escape too large", line)
                out.append(chr(n))
                i = j
            else:
                raise LexError(f"invalid escape sequence '\\{esc}'", line)
        else:
            out.append(c)
            i += 1
    raise LexError("unterminated string", start_line)

_hex = set("0123456789abcdefABCDEF")

def _read_number(src, i, line):
    start = i
    is_float = False
    is_hex = False
    if src[i] == '0' and i + 1 < len(src) and src[i+1] in ('x','X'):
        is_hex = True
        i += 2
        digs = _hex
        while i < len(src) and src[i] in digs:
            i += 1
        if i < len(src) and src[i] == '.':
            is_float = True
            i += 1
            while i < len(src) and src[i] in digs:
                i += 1
        if i < len(src) and src[i] in ('p','P'):
            is_float = True
            i += 1
            if i < len(src) and src[i] in ('+','-'):
                i += 1
            while i < len(src) and src[i].isdigit():
                i += 1
    else:
        while i < len(src) and src[i].isdigit():
            i += 1
        if i < len(src) and src[i] == '.':
            is_float = True
            i += 1
            while i < len(src) and src[i].isdigit():
                i += 1
        if i < len(src) and src[i] in ('e','E'):
            is_float = True
            i += 1
            if i < len(src) and src[i] in ('+','-'):
                i += 1
            while i < len(src) and src[i].isdigit():
                i += 1
    text = src[start:i]
    if is_float:
        if is_hex:
            val = float.fromhex(text)
        else:
            val = float(text)
        return ('FLOAT', val, i)
    else:
        if is_hex:
            val = int(text[2:], 16)
            # Lua hex literals may overflow to unsigned 64-bit wrap
            if val >= (1 << 63):
                val -= (1 << 64)
        else:
            val = int(text)
        # Integer overflow? Lua 5.5 keeps as integer if fits
        return ('INT', val, i)

# Single/multi-char operators
OPS = [
    '...','..','::',
    '==','~=','<=','>=','<<','>>','//',
    '+','-','*','/','%','^','#','&','~','|','<','>','=','(',')','{','}','[',']',';',':',',','.',
]
# Sort by length descending
OPS.sort(key=lambda x: -len(x))

def tokenize(src, chunkname='?'):
    tokens = []
    i = 0
    line = 1
    n = len(src)
    # Skip shebang
    if src.startswith('#!'):
        eol = src.find('\n')
        if eol < 0:
            return [Token('EOF', None, 1)]
        i = eol + 1
        line = 2
    while i < n:
        c = src[i]
        # whitespace
        if c in ' \t\r\v\f':
            i += 1
            continue
        if c == '\n':
            line += 1
            i += 1
            continue
        # comment
        if c == '-' and i + 1 < n and src[i+1] == '-':
            i += 2
            # long comment?
            if i < n and src[i] == '[':
                r = _read_long_bracket(src, i, line)
                if r is not None:
                    _, i, line = r
                    continue
            # line comment
            while i < n and src[i] != '\n':
                i += 1
            continue
        # long string
        if c == '[':
            r = _read_long_bracket(src, i, line)
            if r is not None:
                val, i, line = r
                tokens.append(Token('STRING', val, line))
                continue
        # string
        if c == '"' or c == "'":
            val, i, line = _read_string(src, i, c, line)
            tokens.append(Token('STRING', val, line))
            continue
        # number
        if c.isdigit() or (c == '.' and i + 1 < n and src[i+1].isdigit()):
            t, v, i = _read_number(src, i, line)
            tokens.append(Token(t, v, line))
            continue
        # identifier / keyword
        if c.isalpha() or c == '_':
            j = i
            while j < n and (src[j].isalnum() or src[j] == '_'):
                j += 1
            name = src[i:j]
            if name in KEYWORDS:
                tokens.append(Token(name.upper(), name, line))
            else:
                tokens.append(Token('NAME', name, line))
            i = j
            continue
        # operators
        matched = False
        for op in OPS:
            if src.startswith(op, i):
                tokens.append(Token(op, op, line))
                i += len(op)
                matched = True
                break
        if not matched:
            raise LexError(f"unexpected symbol near {c!r}", line)
    tokens.append(Token('EOF', None, line))
    return tokens
