    # src[i] == quote
    i += 1
    out = []
    start_line = line
    while i < len(src):
        c = src[i]
        if c == quote:
            return ''.join(out), i + 1, line
        if c == '\n' or c == '\r':
            raise LexError("unterminated string", start_line)
        if c == '\\':
            i += 1
            if i >= len(src):
                raise LexError("unterminated string", start_line)
            esc = src[i]
            if esc == 'a': out.append('\a'); i += 1
            elif esc == 'b': out.append('\b'); i += 1
            elif esc == 'f': out.append('\f'); i += 1
            elif esc == 'n': out.append('\n'); i += 1
            elif esc == 'r': out.append('\r'); i += 1
            elif esc == 't': out.append('\t'); i += 1
            elif esc == 'v': out.append('\v'); i += 1
            elif esc == '\\': out.append('\\'); i += 1
            elif esc == '"': out.append('"'); i += 1
            elif esc == "'": out.append("'"); i += 1
            elif esc == '\n':
                out.append('\n'); i += 1; line += 1
            elif esc == '\r':
                out.append('\n'); i += 1
