            return BreakStmt(t.line)
        if ty == 'GOTO':
            self.advance()
            name = self.expect('NAME', "<name> expected")
            return GotoStmt(name.value, t.line)
        if ty == '::':
            self.advance()
            name = self.expect('NAME', "<name> expected")
