        if ty == 'FLOAT':
            self.advance()
            return Number(t.value, True, t.line)
        if ty == 'STRING':
            self.advance()
            return String(t.value, t.line)
        if ty == 'NIL':
            self.advance()
            return Nil(t.line)
        if ty == 'TRUE':
            self.advance()
            return TrueExpr(t.line)
        if ty == 'FALSE':
            self.advance()
            return FalseExpr(t.line)
        if ty == '...':
            self.advance()
            return Vararg(t.line)
        if ty == '{':
            return self.parse_table_constructor()
        if ty == 'FUNCTION':
            self.advance()
            return self.parse_funcbody(t.line)
        return self.parse_suffixed_expr()

    def parse_suffixed_expr(self):
        e = self.parse_primary_expr()
        while True:
            t = self.peek()
            if t.type == '.':
                self.advance()
                n = self.expect('NAME')
                e = Index(e, String(n.value, n.line), n.line)
            elif t.type == '[':
                self.advance()
                k = self.parse_expr()
                self.expect(']')
                e = Index(e, k, t.line)
            elif t.type == ':':
                self.advance()
                n = self.expect('NAME')
                args = self.parse_call_args()
                e = FuncCall(e, args, is_method=True, method_name=n.value, line=t.line)
            elif t.type in ('(','STRING','{'):
                args = self.parse_call_args()
                e = FuncCall(e, args, line=t.line)
            else:
                break
        return e

    def parse_primary_expr(self):
        t = self.peek()
        if t.type == '(':
            self.advance()
            e = self.parse_expr()
            self.expect(')')
            # Wrap in a special "parens" node? Lua truncates to single value.
            # We use a small marker via a FuncCall-like... Actually use a flag on node
            # To keep simple, we introduce a Paren node inline
            return Paren(e, t.line)
        if t.type == 'NAME':
            self.advance()
            return Name(t.value, t.line)
        self._error("unexpected symbol near " + self._tok_str(t), t.line)

    def parse_call_args(self):
        t = self.peek()
        if t.type == '(':
            self.advance()
            args = []
            if not self.check(')'):
                args = self.parse_exprlist()
            self.expect(')')
            return args
        if t.type == 'STRING':
            self.advance()
            return [String(t.value, t.line)]
        if t.type == '{':
            return [self.parse_table_constructor()]
        self._error("function arguments expected", t.line)

    def parse_table_constructor(self):
        t = self.expect('{')
        fields = []
        while not self.check('}'):
            if self.check('['):
                self.advance()
                k = self.parse_expr()
                self.expect(']')
                self.expect('=')
                v = self.parse_expr()
                fields.append(('keyed', k, v))
            elif self.peek().type == 'NAME' and self.peek(1).type == '=':
                name = self.advance().value
                self.advance()  # =
                v = self.parse_expr()
                fields.append(('named', name, v))
            else:
                v = self.parse_expr()
                fields.append(('array', v))
            if self.match(',') or self.match(';'):
                continue
            break
        self.expect('}')
        return TableConstructor(fields, t.line)

class Paren(Node):
    __slots__=('expr','line')
    def __init__(self, expr, line): self.expr=expr; self.line=line

