        if ty == 'INT':
            self.advance()
            return Number(t.value, False, t.line)
        if ty == 'FLOAT':
            self.advance()
            return Number(t.value, True, t.line)
        if ty == 'STRING':
            self.advance()
            return String(t.value, t.line)
        if ty == 'NIL':
            self.advance()
            return Nil(t.line)
        if ty == 'TRUE':
            self.advance()
            return TrueExpr(t.line)
        if ty == 'FALSE':
            self.advance()
            return FalseExpr(t.line)
        if ty == '...':
            self.advance()
            return Vararg(t.line)
        if ty == '{':
            return self.parse_table_constructor()
        if ty == 'FUNCTION':
            self.advance()
            return self.parse_funcbody(t.line)
        return self.parse_suffixed_expr()

    def parse_suffixed_expr(self):
        e = self.parse_primary_expr()
        while True:
            t = self.peek()
            if t.type == '.':
                self.advance()
                n = self.expect('NAME')
                e = Index(e, String(n.value, n.line), n.line)
            elif t.type == '[':
