            self.advance()
            return Name(t.value, t.line)
        self._error("unexpected symbol near " + self._tok_str(t), t.line)

    def parse_call_args(self):
        t = self.peek()
        if t.type == '(':
            self.advance()
            args = []
            if not self.check(')'):
                args = self.parse_exprlist()
            self.expect(')')
            return args
        if t.type == 'STRING':
            self.advance()
            return [String(t.value, t.line)]
        if t.type == '{':
            return [self.parse_table_constructor()]
        self._error("function arguments expected", t.line)

    def parse_table_constructor(self):
        t = self.expect('{')
        fields = []
        while not self.check('}'):
            if self.check('['):
                self.advance()
                k = self.parse_expr()
                self.expect(']')
                self.expect('=')
                v = self.parse_expr()
                fields.append(('keyed', k, v))
            elif self.peek().type == 'NAME' and self.peek(1).type == '=':
