                self.advance()  # =
                v = self.parse_expr()
                fields.append(('named', name, v))
            else:
                v = self.parse_expr()
                fields.append(('array', v))
            if self.match(',') or self.match(';'):
                continue
            break
        self.expect('}')
        return TableConstructor(fields, t.line)

