# Lua parser
from lexer import Token
from ast_nodes import *

class ParseError(Exception):
    def __init__(self, msg, line):
        super().__init__(msg)
        self.line = line

# Operator precedence (Lua 5.4/5.5)
# or
# and
# <     >     <=    >=    ~=    ==
# |
# ~
# &
# <<    >>
# ..
# +     -
# *     /     //    %
# unary not   #     -     ~
# ^
# Right-assoc: .. and ^
BIN_PREC = {
    'or':  (1, 1),
    'and': (2, 2),
    '<':   (3, 3), '>': (3, 3), '<=': (3, 3), '>=': (3, 3), '==': (3, 3), '~=': (3, 3),
    '|':   (4, 4),
    '~':   (5, 5),
    '&':   (6, 6),
    '<<':  (7, 7), '>>': (7, 7),
    '..':  (9, 8),  # right assoc
    '+':   (10, 10), '-': (10, 10),
    '*':   (11, 11), '/': (11, 11), '//': (11, 11), '%': (11, 11),
    '^':   (14, 13), # right assoc
}
UNARY_PREC = 12

UNARY_OPS = {'not','-','#','~'}

class Parser:
    def __init__(self, tokens, chunkname='?'):
        self.tokens = tokens
        self.pos = 0
        self.chunkname = chunkname

    def peek(self, offset=0):
        return self.tokens[self.pos + offset]

    def advance(self):
        t = self.tokens[self.pos]
        self.pos += 1
        return t

    def check(self, *types):
        return self.peek().type in types

    def match(self, *types):
        if self.peek().type in types:
            return self.advance()
        return None

    def expect(self, type, extra=""):
        t = self.peek()
        if t.type != type:
            if extra:
                self._error(f"{extra} near {self._tok_str(t)}")
            else:
                self._error(f"'{type}' expected near {self._tok_str(t)}")
        return self.advance()

    def _tok_str(self, t):
        if t.type == 'EOF':
            return '<eof>'
        if t.type == 'STRING':
            return repr(t.value)
        if t.type == 'INT' or t.type == 'FLOAT':
            return f"'{t.value}'"
        if t.type == 'NAME':
            return f"'{t.value}'"
        return f"'{t.type}'"

    def _error(self, msg, line=None):
        if line is None:
            line = self.peek().line
        raise ParseError(msg, line)

    def parse_chunk(self):
        blk = self.parse_block()
        if self.peek().type != 'EOF':
            self._error(f"'<eof>' expected near {self._tok_str(self.peek())}")
        return blk

    def parse_block(self):
        stmts = []
        while not self._is_block_end():
            if self.check('RETURN'):
                stmts.append(self.parse_return())
                break
            s = self.parse_stmt()
            if s is not None:
                stmts.append(s)
        return Block(stmts)

    def _is_block_end(self):
        t = self.peek().type
        return t in ('EOF','END','ELSE','ELSEIF','UNTIL')

    def parse_stmt(self):
        t = self.peek()
        ty = t.type
        if ty == ';':
            self.advance()
            return None
        if ty == 'IF':
            return self.parse_if()
        if ty == 'WHILE':
            return self.parse_while()
        if ty == 'DO':
            return self.parse_do()
        if ty == 'FOR':
            return self.parse_for()
        if ty == 'REPEAT':
            return self.parse_repeat()
        if ty == 'FUNCTION':
            return self.parse_function_stmt()
        if ty == 'LOCAL':
            return self.parse_local()
        if ty == 'RETURN':
            return self.parse_return()
        if ty == 'BREAK':
            self.advance()
            return BreakStmt(t.line)
        if ty == 'GOTO':
            self.advance()
            name = self.expect('NAME', "<name> expected")
            return GotoStmt(name.value, t.line)
        if ty == '::':
            self.advance()
            name = self.expect('NAME', "<name> expected")
            self.expect('::')
            return LabelStmt(name.value, t.line)
        # expression statement: assignment or function call
        return self.parse_expr_stmt()

    def parse_return(self):
        t = self.advance()  # RETURN
        exprs = []
        if not self._is_block_end() and not self.check(';'):
            exprs = self.parse_exprlist()
        self.match(';')
        return ReturnStmt(exprs, t.line)

    def parse_if(self):
        t = self.advance()  # IF
        cond = self.parse_expr()
        self.expect('THEN')
        then_blk = self.parse_block()
        elseifs = []
        else_blk = None
        while self.check('ELSEIF'):
            self.advance()
            c = self.parse_expr()
            self.expect('THEN')
            b = self.parse_block()
            elseifs.append((c, b))
        if self.match('ELSE'):
            else_blk = self.parse_block()
        self.expect('END')
        return IfStmt(cond, then_blk, elseifs, else_blk, t.line)

    def parse_while(self):
        t = self.advance()
        cond = self.parse_expr()
        self.expect('DO')
        body = self.parse_block()
        self.expect('END')
        return WhileStmt(cond, body, t.line)

    def parse_do(self):
        t = self.advance()
        body = self.parse_block()
        self.expect('END')
        return DoStmt(body, t.line)

    def parse_repeat(self):
        t = self.advance()
        body = self.parse_block()
        self.expect('UNTIL')
        cond = self.parse_expr()
        return RepeatStmt(body, cond, t.line)

    def parse_for(self):
        t = self.advance()  # FOR
        first_name = self.expect('NAME').value
        if self.check('='):
            self.advance()
            start = self.parse_expr()
            self.expect(',')
            stop = self.parse_expr()
            step = None
            if self.match(','):
                step = self.parse_expr()
            self.expect('DO')
            body = self.parse_block()
            self.expect('END')
            return NumericFor(first_name, start, stop, step, body, t.line)
        names = [first_name]
        while self.match(','):
            names.append(self.expect('NAME').value)
        self.expect('IN')
        exprs = self.parse_exprlist()
        self.expect('DO')
        body = self.parse_block()
        self.expect('END')
        return GenericFor(names, exprs, body, t.line)

    def parse_function_stmt(self):
        t = self.advance()  # FUNCTION
        # funcname ::= Name {'.' Name} [':' Name]
        first = self.expect('NAME')
        target = Name(first.value, first.line)
        is_method = False
        method_name = None
        while self.match('.'):
            n = self.expect('NAME')
            target = Index(target, String(n.value, n.line), n.line)
        if self.match(':'):
            n = self.expect('NAME')
            is_method = True
            target = Index(target, String(n.value, n.line), n.line)
        func = self.parse_funcbody(t.line, is_method, name=self._funcname_str(target))
        return AssignStmt([target], [func], t.line)

    def _funcname_str(self, node):
        if isinstance(node, Name):
            return node.name
        if isinstance(node, Index) and isinstance(node.key, String):
            return self._funcname_str(node.obj) + "." + node.key.value
        return "?"

    def parse_funcbody(self, line, is_method=False, name=None):
        self.expect('(')
        params = []
        is_vararg = False
        if is_method:
            params.append('self')
        if not self.check(')'):
            while True:
                if self.check('...'):
                    self.advance()
                    is_vararg = True
                    break
                n = self.expect('NAME')
                params.append(n.value)
                if not self.match(','):
                    break
        self.expect(')')
        body = self.parse_block()
        self.expect('END')
        return FuncExpr(params, is_vararg, body, line, name=name)

    def parse_local(self):
        t = self.advance()  # LOCAL
        if self.match('FUNCTION'):
            n = self.expect('NAME')
            func = self.parse_funcbody(t.line, name=n.value)
            return LocalFunc(n.value, func, t.line)
        names = []
        attribs = []
        while True:
            n = self.expect('NAME')
            attr = None
            if self.match('<'):
                a = self.expect('NAME')
                attr = a.value
                self.expect('>')
            names.append(n.value)
            attribs.append(attr)
            if not self.match(','):
                break
        exprs = []
        if self.match('='):
            exprs = self.parse_exprlist()
        return LocalStmt(names, attribs, exprs, t.line)

    def parse_expr_stmt(self):
        line = self.peek().line
        e = self.parse_suffixed_expr()
        if self.check('=', ','):
