        if not isinstance(e, FuncCall):
            self._error("syntax error near " + self._tok_str(self.peek()), line)
        return ExprStmt(e, line)

    def parse_exprlist(self):
        exprs = [self.parse_expr()]
        while self.match(','):
            exprs.append(self.parse_expr())
        return exprs

