# Lua value types and helpers
import math

class LuaError(Exception):
    """Wraps a Lua value thrown via error()."""
    def __init__(self, value, level=1, traceback=None):
        self.value = value
        self.level = level
        self.traceback = traceback
        super().__init__(str(value) if isinstance(value, str) else repr(value))

class BreakException(Exception): pass
class ContinueException(Exception): pass
class GotoException(Exception):
    def __init__(self, label):
        self.label = label
class ReturnException(Exception):
    def __init__(self, values):
        self.values = values

# Integer range
INT_MIN = -(1 << 63)
INT_MAX = (1 << 63) - 1
UINT_MOD = 1 << 64

def int_wrap(x):
    """Wrap Python int to Lua int64 range."""
    x = x & (UINT_MOD - 1)
    if x >= (1 << 63):
        x -= UINT_MOD
    return x

def is_lua_int(v):
    return isinstance(v, int) and not isinstance(v, bool)

def is_lua_float(v):
    return isinstance(v, float)

def is_lua_number(v):
    return (isinstance(v, int) and not isinstance(v, bool)) or isinstance(v, float)

def is_lua_string(v):
    return isinstance(v, str)

def lua_type(v):
    if v is None: return 'nil'
    if isinstance(v, bool): return 'boolean'
    if isinstance(v, int) or isinstance(v, float): return 'number'
    if isinstance(v, str): return 'string'
    if isinstance(v, LuaTable): return 'table'
    if callable(v) or isinstance(v, LuaFunction) or isinstance(v, BuiltinFunction):
        return 'function'
    return 'userdata'

def is_true(v):
    return v is not None and v is not False

# Number formatting: %.17g with .0 appended if whole float without 'e' or '.'
def num_to_str(v):
    if isinstance(v, bool):
        return 'true' if v else 'false'
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        if math.isnan(v):
            # Lua prints -nan if sign bit is set; we don't track it; always 'nan' or '-nan'?
            # Python: math.copysign(1, v) can tell
            if math.copysign(1.0, v) < 0:
                return '-nan'
            return 'nan'
        if math.isinf(v):
            return '-inf' if v < 0 else 'inf'
        s = format(v, '.17g')
        # normalize: python gives '1e+100' (with +), C gives '1e+100' too. OK
        # Lua appends .0 if no . and no e and no inf/nan
        if '.' not in s and 'e' not in s and 'E' not in s and 'n' not in s and 'i' not in s:
            s += '.0'
        return s
    return None

def _checknum_or_str(s):
    """Convert string to number (int or float) Lua-style, or return None."""
    if not isinstance(s, str):
        return None
    t = s.strip()
    if not t:
        return None
    # Try int (dec or hex)
    try:
        if t.lower().startswith('0x') or t.lower().startswith('-0x') or t.lower().startswith('+0x'):
            # hex int
            neg = False
            tt = t
            if tt.startswith('-'):
                neg = True; tt = tt[1:]
            elif tt.startswith('+'):
                tt = tt[1:]
            if '.' in tt or 'p' in tt.lower():
                v = float.fromhex(tt)
                return -v if neg else v
            else:
                v = int(tt, 16)
                if v >= (1 << 63):
                    v -= (1 << 64)
                return -v if neg else v
        # decimal int
        if '.' not in t and 'e' not in t and 'E' not in t:
            return int(t)
        return float(t)
    except ValueError:
        try:
            return float(t)
        except ValueError:
            return None

def tonumber(v, base=None):
    if base is not None:
        if not isinstance(v, str):
            raise LuaError("bad argument #1 to 'tonumber' (string expected)")
        b = int(base) if not isinstance(base, int) or isinstance(base, bool) else base
        try:
            return int(v.strip(), b)
        except ValueError:
            return None
    if is_lua_int(v) or is_lua_float(v):
        return v
    if isinstance(v, str):
        return _checknum_or_str(v)
    return None

def tointeger(v):
    """Convert to Lua integer if possible, else None."""
    if isinstance(v, bool): return None
    if isinstance(v, int): return v
    if isinstance(v, float):
        if math.isnan(v) or math.isinf(v):
            return None
        if v != math.floor(v):
            return None
        if v < INT_MIN or v > INT_MAX:
            return None
        return int(v)
    if isinstance(v, str):
        n = _checknum_or_str(v)
        if n is None: return None
        return tointeger(n)
    return None

def arith_checknum(v, op):
    if isinstance(v, bool):
        raise LuaError(f"attempt to perform arithmetic on a boolean value")
    if isinstance(v, int) or isinstance(v, float):
        return v
    if isinstance(v, str):
        n = _checknum_or_str(v)
        if n is not None:
            return n
    raise LuaError(f"attempt to perform arithmetic on a {lua_type(v)} value")

class LuaTable:
    __slots__ = ('hash','array','metatable')
    def __init__(self):
        self.hash = {}
        self.array = []   # 1-indexed conceptually; index i corresponds to array[i-1]
        self.metatable = None

    def _norm_key(self, k):
        if k is None:
            raise LuaError("table index is nil")
        if isinstance(k, float):
            if math.isnan(k):
                raise LuaError("table index is NaN")
            # Convert float to int if integral
            if k == math.floor(k) and INT_MIN <= k <= INT_MAX:
                return int(k)
        return k

    def rawget(self, k):
        try:
            k = self._norm_key(k)
        except LuaError:
            return None
        if isinstance(k, int) and not isinstance(k, bool):
            if 1 <= k <= len(self.array):
                v = self.array[k-1]
                return v if v is not None else None
