    return {'add':'add','sub':'sub','mul':'mul','div':'div','mod':'mod','pow':'pow','idiv':'idiv','unm':'unm','concat':'concat','len':'len','eq':'eq','lt':'lt','le':'le','band':'band','bor':'bor','bxor':'bxor','shl':'shl','shr':'shr','bnot':'bnot'}[op]

