class Scope:
    __slots__=('vars','parent')
    def __init__(self, parent=None):
        self.vars = {}
        self.parent = parent
    def get(self, name):
        s = self
        while s is not None:
            if name in s.vars:
                return s.vars[name]
            s = s.parent
        return ('notfound',)
    def get_ref(self, name):
        s = self
        while s is not None:
            if name in s.vars:
                return s
            s = s.parent
        return None
