    # ---- Evaluation ----
    def _eval_exprlist(self, exprs, scope, want):
        """Eval list of expressions; if last is multi-valued, expand.
        want == -1 means keep all; otherwise want N values."""
        if not exprs:
            vals = []
        else:
            vals = []
            for e in exprs[:-1]:
                vals.append(self._eval_expr(e, scope))
            last = exprs[-1]
            lv = self._eval_expr(last, scope, multi=True)
            if isinstance(lv, list):
                vals.extend(lv)
            else:
                vals.append(lv)
        if want == -1:
            return vals
        # pad/trunc
        if len(vals) < want:
            vals = vals + [None]*(want - len(vals))
        else:
            vals = vals[:want]
        return vals

    def _eval_expr(self, e, scope, multi=False):
        self.current_line = getattr(e, 'line', self.current_line)
        if isinstance(e, Nil): return None
        if isinstance(e, TrueExpr): return True
        if isinstance(e, FalseExpr): return False
        if isinstance(e, Number):
            return e.value
        if isinstance(e, String):
            return e.value
        if isinstance(e, Vararg):
            va = scope.get('...')
            vals = va if va and va[0] != 'notfound' else None
            v = scope.get('...')
            if v == ('notfound',):
                raise LuaError("cannot use '...' outside a vararg function")
            if multi:
                return list(v)
            return v[0] if v else None
        if isinstance(e, Name):
            v = scope.get(e.name)
            if v == ('notfound',):
                return self.globals.rawget(e.name)
            return v
        if isinstance(e, Index):
            obj = self._eval_expr(e.obj, scope)
            key = self._eval_expr(e.key, scope)
            return self._index_get(obj, key)
        if isinstance(e, BinOp):
            return self._eval_binop(e, scope)
        if isinstance(e, UnOp):
            return self._eval_unop(e, scope)
        if isinstance(e, FuncCall):
            vals = self._eval_funccall(e, scope)
            if multi:
                return vals
            return vals[0] if vals else None
        if isinstance(e, FuncExpr):
            return self._make_closure(e, scope)
        if isinstance(e, TableConstructor):
            return self._eval_table(e, scope)
        if isinstance(e, _parser.Paren):
            v = self._eval_expr(e.expr, scope, multi=True)
            if isinstance(v, list):
                return v[0] if v else None
            return v
        raise LuaError(f"unknown expr: {type(e).__name__}")

    def _make_closure(self, func_expr, scope):
        return LuaFunction(
            func_expr.params, func_expr.is_vararg, func_expr.body, scope,
            name=func_expr.name, chunkname=self.chunkname, line=func_expr.line
        )

    def _eval_table(self, t, scope):
        tbl = LuaTable()
        array_idx = 1
        last_i = len(t.fields) - 1
        for i, f in enumerate(t.fields):
            kind = f[0]
            if kind == 'array':
                expr = f[1]
                if i == last_i:
                    v = self._eval_expr(expr, scope, multi=True)
                    if isinstance(v, list):
                        for x in v:
                            tbl.rawset(array_idx, x)
                            array_idx += 1
                    else:
                        tbl.rawset(array_idx, v)
                        array_idx += 1
                else:
                    v = self._eval_expr(expr, scope)
                    tbl.rawset(array_idx, v)
                    array_idx += 1
            elif kind == 'named':
                name, expr = f[1], f[2]
                v = self._eval_expr(expr, scope)
                tbl.rawset(name, v)
            elif kind == 'keyed':
                k_expr, v_expr = f[1], f[2]
                k = self._eval_expr(k_expr, scope)
                v = self._eval_expr(v_expr, scope)
                tbl.rawset(k, v)
        return tbl

    def _eval_binop(self, e, scope):
        op = e.op
        if op == 'and':
            l = self._eval_expr(e.left, scope)
            if not is_true(l):
                return l
            return self._eval_expr(e.right, scope)
        if op == 'or':
            l = self._eval_expr(e.left, scope)
            if is_true(l):
                return l
            return self._eval_expr(e.right, scope)
        a = self._eval_expr(e.left, scope)
        b = self._eval_expr(e.right, scope)
        if op == '+': return self._arith('add', a, b)
        if op == '-': return self._arith('sub', a, b)
        if op == '*': return self._arith('mul', a, b)
        if op == '/': return self._arith('div', a, b)
        if op == '//': return self._arith('idiv', a, b)
        if op == '%': return self._arith('mod', a, b)
        if op == '^': return self._arith('pow', a, b)
        if op == '..': return self._concat(a, b)
        if op == '==': return self._equals(a, b)
        if op == '~=': return not self._equals(a, b)
        if op == '<': return self._compare_lt(a, b)
        if op == '>': return self._compare_lt(b, a)
        if op == '<=': return self._compare_le(a, b)
        if op == '>=': return self._compare_le(b, a)
        if op == '&': return self._bit('band', a, b)
        if op == '|': return self._bit('bor', a, b)
        if op == '~': return self._bit('bxor', a, b)
        if op == '<<': return self._bit('shl', a, b)
        if op == '>>': return self._bit('shr', a, b)
        raise LuaError(f"unknown binop {op}")

    def _eval_unop(self, e, scope):
        op = e.op
        v = self._eval_expr(e.operand, scope)
        if op == '-':
            return self._arith('unm', v, v)
        if op == 'not':
            return not is_true(v)
        if op == '#':
            return self._len(v)
        if op == '~':
            return self._bit('bnot', v, v)
        raise LuaError(f"unknown unop {op}")

    def _eval_funccall(self, e, scope):
        if e.is_method:
            obj = self._eval_expr(e.func, scope)
            fn = self._index_get(obj, e.method_name)
            args = [obj]
            if e.args:
                args.extend(self._eval_args(e.args, scope))
            return self._call_value(fn, args)
        fn = self._eval_expr(e.func, scope)
        args = self._eval_args(e.args, scope)
        return self._call_value(fn, args)

    def _eval_args(self, args, scope):
        if not args: return []
        out = []
        for a in args[:-1]:
            out.append(self._eval_expr(a, scope))
        last = self._eval_expr(args[-1], scope, multi=True)
        if isinstance(last, list):
            out.extend(last)
        else:
            out.append(last)
        return out

def _op_meta_name(op):
    return {'add':'add','sub':'sub','mul':'mul','div':'div','mod':'mod','pow':'pow','idiv':'idiv','unm':'unm','concat':'concat','len':'len','eq':'eq','lt':'lt','le':'le','band':'band','bor':'bor','bxor':'bxor','shl':'shl','shr':'shr','bnot':'bnot'}[op]

def _num_arith(a, b, fn, int_wrap=False):
    if is_lua_int(a) and is_lua_int(b):
        r = fn(a, b)
        if int_wrap and isinstance(r, int):
            return globals_int_wrap(r)
        return r
    return fn(float(a), float(b))

def globals_int_wrap(x):
    return int_wrap(x)
