            self._eval_expr(s.expr, scope, multi=True)
            return
        if isinstance(s, IfStmt):
            self.current_line = s.line
            if is_true(self._eval_expr(s.cond, scope)):
                self.exec_block(s.then_blk, Scope(scope))
                return
