# Lua tree-walking interpreter
import math
from lua_types import *
from ast_nodes import *
import parser as _parser  # for Paren

class Scope:
    __slots__=('vars','parent')
    def __init__(self, parent=None):
        self.vars = {}
        self.parent = parent
    def get(self, name):
        s = self
        while s is not None:
            if name in s.vars:
                return s.vars[name]
            s = s.parent
        return ('notfound',)
    def get_ref(self, name):
        s = self
        while s is not None:
            if name in s.vars:
                return s
            s = s.parent
        return None
    def set_local(self, name, value):
        self.vars[name] = value
    def set_if_exists(self, name, value):
        s = self.get_ref(name)
        if s is not None:
            s.vars[name] = value
            return True
        return False

class CallFrame:
    __slots__=('name','chunkname','line','is_c')
    def __init__(self, name, chunkname, line, is_c=False):
        self.name=name; self.chunkname=chunkname; self.line=line; self.is_c=is_c

class Interpreter:
    def __init__(self, globals_tbl, chunkname='?'):
        self.globals = globals_tbl
        self.chunkname = chunkname
        self.call_stack = []  # list of CallFrame
        self.current_line = 0

    # ---- metatable helpers ----
    def _get_metatable(self, v):
        if isinstance(v, LuaTable):
            return v.metatable
        # strings have a default metatable
        if isinstance(v, str):
            return self.globals.rawget('__string_mt__')
        return None

    def _get_meta(self, v, event):
        mt = self._get_metatable(v)
        if mt is None:
            return None
        return mt.rawget(event)

    def _index_get(self, obj, key):
        # a[k]
        if isinstance(obj, LuaTable):
            v = obj.rawget(key)
            if v is not None:
                return v
            idx = self._get_meta(obj, '__index')
            if idx is None:
                return None
            if isinstance(idx, LuaTable):
                return self._index_get(idx, key)
            return self._call_value(idx, [obj, key])[0] if self._call_value(idx, [obj, key]) else None
        if isinstance(obj, str):
            idx = self._get_meta(obj, '__index')
            if isinstance(idx, LuaTable):
                return self._index_get(idx, key)
            if idx is not None:
                r = self._call_value(idx, [obj, key])
                return r[0] if r else None
            return None
        if obj is None:
            raise LuaError(f"attempt to index a nil value")
        # other types
        idx = self._get_meta(obj, '__index')
        if idx is None:
            raise LuaError(f"attempt to index a {lua_type(obj)} value")
        if isinstance(idx, LuaTable):
            return self._index_get(idx, key)
        r = self._call_value(idx, [obj, key])
        return r[0] if r else None

    def _index_set(self, obj, key, value):
        if isinstance(obj, LuaTable):
            existing = obj.rawget(key)
            if existing is None:
                ni = self._get_meta(obj, '__newindex')
                if ni is not None:
                    if isinstance(ni, LuaTable):
                        self._index_set(ni, key, value)
                        return
                    self._call_value(ni, [obj, key, value])
                    return
            obj.rawset(key, value)
            return
        if obj is None:
            raise LuaError(f"attempt to index a nil value")
        ni = self._get_meta(obj, '__newindex')
        if ni is None:
            raise LuaError(f"attempt to index a {lua_type(obj)} value")
        if isinstance(ni, LuaTable):
            self._index_set(ni, key, value)
            return
        self._call_value(ni, [obj, key, value])

    # ---- arithmetic ----
    def _arith(self, op, a, b):
        # Handle int/float distinction
        ta = self._get_meta(a, '__' + _op_meta_name(op)) if op != 'unm' else None
        # Coerce strings to numbers when possible
        if op in ('add','sub','mul','mod','pow','unm','idiv','div'):
            pass
        na = a
        nb = b
        if op != 'unm':
            if isinstance(a, str):
                n = _checknum_or_str(a)
                if n is not None: na = n
            if isinstance(b, str):
                n = _checknum_or_str(b)
                if n is not None: nb = n
        if op == 'add':
            if is_lua_number(na) and is_lua_number(nb):
                return _num_arith(na, nb, lambda x,y: x+y, int_wrap=True)
        elif op == 'sub':
            if is_lua_number(na) and is_lua_number(nb):
                return _num_arith(na, nb, lambda x,y: x-y, int_wrap=True)
        elif op == 'mul':
            if is_lua_number(na) and is_lua_number(nb):
                return _num_arith(na, nb, lambda x,y: x*y, int_wrap=True)
        elif op == 'div':
            if is_lua_number(na) and is_lua_number(nb):
                return float(na) / float(nb) if float(nb) != 0 else (math.inf if float(na)>0 else -math.inf if float(na)<0 else float('nan'))
        elif op == 'idiv':
            if is_lua_number(na) and is_lua_number(nb):
                if is_lua_int(na) and is_lua_int(nb):
                    if nb == 0:
                        raise LuaError("attempt to perform 'n//0'")
                    return int_wrap(na // nb)
                f = float(na) / float(nb) if float(nb) != 0 else (math.inf if float(na)>0 else -math.inf if float(na)<0 else float('nan'))
                return math.floor(f) + 0.0 if not (math.isnan(f) or math.isinf(f)) else f
        elif op == 'mod':
            if is_lua_number(na) and is_lua_number(nb):
                if is_lua_int(na) and is_lua_int(nb):
                    if nb == 0:
                        raise LuaError("attempt to perform 'n%%0'")
                    return int_wrap(na - (na // nb) * nb)
                fa = float(na); fb = float(nb)
                if math.isnan(fa) or math.isnan(fb):
                    return float('nan')
                if fb == 0:
                    return float('nan')
                return fa - math.floor(fa/fb) * fb
        elif op == 'pow':
            if is_lua_number(na) and is_lua_number(nb):
                r = math.pow(float(na), float(nb))
                return r
        elif op == 'unm':
            if is_lua_int(na):
                return int_wrap(-na)
            if is_lua_float(na):
                return -na
        # metamethod fallback
        if op != 'unm':
            mm = self._get_meta(a, '__'+op) or self._get_meta(b, '__'+op)
            if mm is not None:
                r = self._call_value(mm, [a,b])
                return r[0] if r else None
            self._arith_error(a, b, op)
        else:
            mm = self._get_meta(a, '__unm')
            if mm is not None:
                r = self._call_value(mm, [a,a])
                return r[0] if r else None
            self._arith_error(a, a, op)

    def _arith_error(self, a, b, op):
        x = a
        if is_lua_number(x) or (isinstance(x, str) and _checknum_or_str(x) is not None):
            x = b
        raise LuaError(f"attempt to perform arithmetic on a {lua_type(x)} value")

    def _bit(self, op, a, b):
        def toint(x):
            r = tointeger(x)
            if r is None:
                raise LuaError(f"attempt to perform bitwise operation on a {lua_type(x)} value")
            return r
        if op == 'bnot':
            return int_wrap(~toint(a))
        ia, ib = toint(a), toint(b)
        if op == 'band': return int_wrap(ia & ib)
        if op == 'bor':  return int_wrap(ia | ib)
        if op == 'bxor': return int_wrap(ia ^ ib)
        if op == 'shl':
            if ib >= 64: return 0
            if ib <= -64: return 0
            if ib >= 0:
                return int_wrap((ia & ((1<<64)-1)) << ib)
            else:
                return int_wrap((ia & ((1<<64)-1)) >> -ib)
        if op == 'shr':
            if ib >= 64: return 0
            if ib <= -64: return 0
            if ib >= 0:
                return int_wrap((ia & ((1<<64)-1)) >> ib)
            else:
                return int_wrap((ia & ((1<<64)-1)) << -ib)

    def _compare_lt(self, a, b):
        if is_lua_number(a) and is_lua_number(b):
            if is_lua_int(a) and is_lua_int(b):
                return a < b
            return float(a) < float(b)
        if isinstance(a, str) and isinstance(b, str):
            return a < b
        mm = self._get_meta(a, '__lt') or self._get_meta(b, '__lt')
        if mm is not None:
            r = self._call_value(mm, [a,b])
            return is_true(r[0] if r else None)
        raise LuaError(f"attempt to compare {lua_type(a)} with {lua_type(b)}")

    def _compare_le(self, a, b):
        if is_lua_number(a) and is_lua_number(b):
            if is_lua_int(a) and is_lua_int(b):
                return a <= b
            return float(a) <= float(b)
        if isinstance(a, str) and isinstance(b, str):
            return a <= b
        mm = self._get_meta(a, '__le') or self._get_meta(b, '__le')
        if mm is not None:
            r = self._call_value(mm, [a,b])
            return is_true(r[0] if r else None)
        mm = self._get_meta(a, '__lt') or self._get_meta(b, '__lt')
        if mm is not None:
            r = self._call_value(mm, [b,a])
            return not is_true(r[0] if r else None)
        raise LuaError(f"attempt to compare {lua_type(a)} with {lua_type(b)}")

    def _equals(self, a, b):
        if a is None and b is None: return True
        if a is None or b is None: return False
        if isinstance(a, bool) or isinstance(b, bool):
            if isinstance(a, bool) and isinstance(b, bool):
                return a == b
            return False
        if is_lua_number(a) and is_lua_number(b):
            if is_lua_int(a) and is_lua_int(b):
                return a == b
            return float(a) == float(b)
        if isinstance(a, str) and isinstance(b, str):
            return a == b
        if type(a) is not type(b):
            return False
        if a is b:
            return True
        if isinstance(a, LuaTable):
            mm = self._get_meta(a, '__eq') or self._get_meta(b, '__eq')
            if mm is not None:
                r = self._call_value(mm, [a,b])
                return is_true(r[0] if r else None)
        return False

    def _concat(self, a, b):
        if (isinstance(a, str) or is_lua_number(a)) and (isinstance(b, str) or is_lua_number(b)):
            return self._tostring_concat(a) + self._tostring_concat(b)
        mm = self._get_meta(a, '__concat') or self._get_meta(b, '__concat')
        if mm is not None:
            r = self._call_value(mm, [a,b])
            return r[0] if r else None
        x = a if not (isinstance(a, str) or is_lua_number(a)) else b
        raise LuaError(f"attempt to concatenate a {lua_type(x)} value")

    def _tostring_concat(self, v):
        if isinstance(v, str): return v
        if is_lua_int(v): return str(v)
        if is_lua_float(v): return num_to_str(v)
        raise LuaError("concat")

    def _len(self, v):
        if isinstance(v, str):
            return len(v.encode('utf-8', errors='surrogatepass'))
        if isinstance(v, LuaTable):
            mm = self._get_meta(v, '__len')
            if mm is not None:
                r = self._call_value(mm, [v])
                return r[0] if r else None
            return v.length()
        mm = self._get_meta(v, '__len')
        if mm is not None:
            r = self._call_value(mm, [v])
            return r[0] if r else None
        raise LuaError(f"attempt to get length of a {lua_type(v)} value")

    # ---- Call handling ----
    def _call_value(self, fn, args):
        if isinstance(fn, LuaFunction):
            return self._call_lua(fn, args)
        if isinstance(fn, BuiltinFunction):
            try:
                r = fn.fn(self, args)
            except LuaError:
                raise
            if r is None:
                return []
            if isinstance(r, list):
                return r
            return [r]
        if callable(fn) and not isinstance(fn, (LuaTable, LuaFunction)):
            r = fn(self, args)
            if r is None: return []
            if isinstance(r, list): return r
            return [r]
        # __call metamethod
        if fn is None:
            raise LuaError("attempt to call a nil value")
        mm = self._get_meta(fn, '__call')
        if mm is not None:
            return self._call_value(mm, [fn] + args)
        raise LuaError(f"attempt to call a {lua_type(fn)} value")

    def _call_lua(self, fn, args):
        scope = Scope(fn.env)
        for i, p in enumerate(fn.params):
            scope.set_local(p, args[i] if i < len(args) else None)
        if fn.is_vararg:
            scope.set_local('...', args[len(fn.params):])
        frame = CallFrame(fn.name, fn.chunkname, fn.line)
        self.call_stack.append(frame)
        try:
            try:
                self.exec_block(fn.body, scope)
            except ReturnException as r:
                return r.values
            return []
        finally:
            self.call_stack.pop()

    # ---- Execution ----
    def exec_block(self, blk, scope):
        stmts = blk.stmts
        i = 0
        while i < len(stmts):
            s = stmts[i]
            try:
                self.exec_stmt(s, scope)
            except GotoException as g:
                # find label in this block (or enclosing)
                found = -1
                for j, ss in enumerate(stmts):
                    if isinstance(ss, LabelStmt) and ss.name == g.label:
                        found = j; break
                if found >= 0:
                    # create a new scope for goto continuation? Lua local vars stay
                    i = found + 1
                    continue
                raise
            i += 1

    def exec_stmt(self, s, scope):
        if isinstance(s, LocalStmt):
            values = self._eval_exprlist(s.exprs, scope, len(s.names))
            for name, val in zip(s.names, values):
                scope.set_local(name, val)
            return
        if isinstance(s, LocalFunc):
            # Define name first so recursion works
            scope.set_local(s.name, None)
            fn = self._make_closure(s.func, scope)
            scope.set_local(s.name, fn)
            return
        if isinstance(s, AssignStmt):
            values = self._eval_exprlist(s.exprs, scope, len(s.targets))
            # Evaluate target access info first
            accessors = []
            for t in s.targets:
                if isinstance(t, Name):
                    accessors.append(('name', t.name))
                elif isinstance(t, Index):
                    obj = self._eval_expr(t.obj, scope)
                    key = self._eval_expr(t.key, scope)
                    accessors.append(('index', obj, key))
                else:
                    raise LuaError("invalid assignment target")
            for acc, val in zip(accessors, values):
                if acc[0] == 'name':
                    name = acc[1]
                    if not scope.set_if_exists(name, val):
                        # global
                        self.globals.rawset(name, val)
                else:
                    _, obj, key = acc
                    self._index_set(obj, key, val)
            return
        if isinstance(s, ExprStmt):
            self._eval_expr(s.expr, scope, multi=True)
            return
        if isinstance(s, IfStmt):
            self.current_line = s.line
            if is_true(self._eval_expr(s.cond, scope)):
                self.exec_block(s.then_blk, Scope(scope))
                return
            for c, b in s.elseifs:
                if is_true(self._eval_expr(c, scope)):
                    self.exec_block(b, Scope(scope))
                    return
            if s.else_blk is not None:
                self.exec_block(s.else_blk, Scope(scope))
            return
        if isinstance(s, WhileStmt):
            while is_true(self._eval_expr(s.cond, scope)):
                try:
                    self.exec_block(s.body, Scope(scope))
                except BreakException:
                    return
            return
        if isinstance(s, RepeatStmt):
            while True:
                inner = Scope(scope)
                try:
                    self.exec_block(s.body, inner)
                except BreakException:
                    return
                if is_true(self._eval_expr(s.cond, inner)):
                    return
        if isinstance(s, NumericFor):
            start = self._eval_expr(s.start, scope)
            stop = self._eval_expr(s.stop, scope)
            step = self._eval_expr(s.step, scope) if s.step is not None else 1
            # determine numeric types
            def to_n(x, which):
                if is_lua_number(x):
                    return x
                n = _checknum_or_str(x) if isinstance(x, str) else None
                if n is None:
                    raise LuaError(f"'for' {which} must be a number")
                return n
            start = to_n(start, 'initial value')
            stop = to_n(stop, 'limit')
            step = to_n(step, 'step')
            if step == 0:
                raise LuaError("'for' step is zero")
            all_int = is_lua_int(start) and is_lua_int(stop) and is_lua_int(step)
            if not all_int:
                start = float(start); stop = float(stop); step = float(step)
            i = start
            while (step > 0 and i <= stop) or (step < 0 and i >= stop):
                inner = Scope(scope)
                inner.set_local(s.var, i)
                try:
                    self.exec_block(s.body, inner)
                except BreakException:
                    return
                i = i + step
                if all_int:
                    i = int_wrap(i)
            return
        if isinstance(s, GenericFor):
            values = self._eval_exprlist(s.exprs, scope, 4)
            while len(values) < 4:
                values.append(None)
            iter_fn, state, ctrl, _close = values
            while True:
                r = self._call_value(iter_fn, [state, ctrl])
                if not r or r[0] is None:
                    return
                ctrl = r[0]
                inner = Scope(scope)
                for i, nm in enumerate(s.names):
                    inner.set_local(nm, r[i] if i < len(r) else None)
                try:
                    self.exec_block(s.body, inner)
                except BreakException:
                    return
        if isinstance(s, ReturnStmt):
            values = self._eval_exprlist(s.exprs, scope, -1)
            raise ReturnException(values)
        if isinstance(s, BreakStmt):
            raise BreakException()
        if isinstance(s, GotoStmt):
            raise GotoException(s.label)
        if isinstance(s, LabelStmt):
            return
        if isinstance(s, DoStmt):
            self.exec_block(s.body, Scope(scope))
            return
        raise LuaError(f"unknown stmt: {type(s).__name__}")

    # ---- Evaluation ----
    def _eval_exprlist(self, exprs, scope, want):
        """Eval list of expressions; if last is multi-valued, expand.
        want == -1 means keep all; otherwise want N values."""
        if not exprs:
            vals = []
        else:
            vals = []
            for e in exprs[:-1]:
                vals.append(self._eval_expr(e, scope))
            last = exprs[-1]
            lv = self._eval_expr(last, scope, multi=True)
            if isinstance(lv, list):
                vals.extend(lv)
            else:
                vals.append(lv)
        if want == -1:
            return vals
        # pad/trunc
        if len(vals) < want:
            vals = vals + [None]*(want - len(vals))
        else:
            vals = vals[:want]
        return vals

    def _eval_expr(self, e, scope, multi=False):
        self.current_line = getattr(e, 'line', self.current_line)
        if isinstance(e, Nil): return None
        if isinstance(e, TrueExpr): return True
        if isinstance(e, FalseExpr): return False
        if isinstance(e, Number):
            return e.value
        if isinstance(e, String):
            return e.value
        if isinstance(e, Vararg):
            va = scope.get('...')
            vals = va if va and va[0] != 'notfound' else None
            v = scope.get('...')
            if v == ('notfound',):
                raise LuaError("cannot use '...' outside a vararg function")
            if multi:
                return list(v)
            return v[0] if v else None
        if isinstance(e, Name):
            v = scope.get(e.name)
            if v == ('notfound',):
                return self.globals.rawget(e.name)
            return v
        if isinstance(e, Index):
            obj = self._eval_expr(e.obj, scope)
            key = self._eval_expr(e.key, scope)
            return self._index_get(obj, key)
        if isinstance(e, BinOp):
            return self._eval_binop(e, scope)
        if isinstance(e, UnOp):
            return self._eval_unop(e, scope)
        if isinstance(e, FuncCall):
            vals = self._eval_funccall(e, scope)
            if multi:
                return vals
            return vals[0] if vals else None
        if isinstance(e, FuncExpr):
            return self._make_closure(e, scope)
        if isinstance(e, TableConstructor):
            return self._eval_table(e, scope)
        if isinstance(e, _parser.Paren):
            v = self._eval_expr(e.expr, scope, multi=True)
            if isinstance(v, list):
                return v[0] if v else None
            return v
        raise LuaError(f"unknown expr: {type(e).__name__}")

    def _make_closure(self, func_expr, scope):
        return LuaFunction(
            func_expr.params, func_expr.is_vararg, func_expr.body, scope,
            name=func_expr.name, chunkname=self.chunkname, line=func_expr.line
        )

    def _eval_table(self, t, scope):
        tbl = LuaTable()
        array_idx = 1
        last_i = len(t.fields) - 1
        for i, f in enumerate(t.fields):
            kind = f[0]
            if kind == 'array':
                expr = f[1]
                if i == last_i:
                    v = self._eval_expr(expr, scope, multi=True)
                    if isinstance(v, list):
                        for x in v:
                            tbl.rawset(array_idx, x)
                            array_idx += 1
                    else:
                        tbl.rawset(array_idx, v)
                        array_idx += 1
                else:
                    v = self._eval_expr(expr, scope)
                    tbl.rawset(array_idx, v)
                    array_idx += 1
            elif kind == 'named':
                name, expr = f[1], f[2]
                v = self._eval_expr(expr, scope)
                tbl.rawset(name, v)
            elif kind == 'keyed':
                k_expr, v_expr = f[1], f[2]
                k = self._eval_expr(k_expr, scope)
                v = self._eval_expr(v_expr, scope)
                tbl.rawset(k, v)
        return tbl

    def _eval_binop(self, e, scope):
        op = e.op
        if op == 'and':
            l = self._eval_expr(e.left, scope)
            if not is_true(l):
                return l
            return self._eval_expr(e.right, scope)
        if op == 'or':
            l = self._eval_expr(e.left, scope)
            if is_true(l):
                return l
            return self._eval_expr(e.right, scope)
        a = self._eval_expr(e.left, scope)
        b = self._eval_expr(e.right, scope)
        if op == '+': return self._arith('add', a, b)
        if op == '-': return self._arith('sub', a, b)
        if op == '*': return self._arith('mul', a, b)
        if op == '/': return self._arith('div', a, b)
        if op == '//': return self._arith('idiv', a, b)
        if op == '%': return self._arith('mod', a, b)
        if op == '^': return self._arith('pow', a, b)
        if op == '..': return self._concat(a, b)
        if op == '==': return self._equals(a, b)
        if op == '~=': return not self._equals(a, b)
        if op == '<': return self._compare_lt(a, b)
        if op == '>': return self._compare_lt(b, a)
        if op == '<=': return self._compare_le(a, b)
        if op == '>=': return self._compare_le(b, a)
        if op == '&': return self._bit('band', a, b)
        if op == '|': return self._bit('bor', a, b)
        if op == '~': return self._bit('bxor', a, b)
        if op == '<<': return self._bit('shl', a, b)
        if op == '>>': return self._bit('shr', a, b)
        raise LuaError(f"unknown binop {op}")

    def _eval_unop(self, e, scope):
        op = e.op
        v = self._eval_expr(e.operand, scope)
        if op == '-':
            return self._arith('unm', v, v)
        if op == 'not':
            return not is_true(v)
        if op == '#':
            return self._len(v)
        if op == '~':
            return self._bit('bnot', v, v)
        raise LuaError(f"unknown unop {op}")

    def _eval_funccall(self, e, scope):
        if e.is_method:
            obj = self._eval_expr(e.func, scope)
            fn = self._index_get(obj, e.method_name)
            args = [obj]
            if e.args:
                args.extend(self._eval_args(e.args, scope))
            return self._call_value(fn, args)
        fn = self._eval_expr(e.func, scope)
        args = self._eval_args(e.args, scope)
        return self._call_value(fn, args)

    def _eval_args(self, args, scope):
        if not args: return []
        out = []
        for a in args[:-1]:
            out.append(self._eval_expr(a, scope))
        last = self._eval_expr(args[-1], scope, multi=True)
        if isinstance(last, list):
            out.extend(last)
        else:
            out.append(last)
        return out

def _op_meta_name(op):
    return {'add':'add','sub':'sub','mul':'mul','div':'div','mod':'mod','pow':'pow','idiv':'idiv','unm':'unm','concat':'concat','len':'len','eq':'eq','lt':'lt','le':'le','band':'band','bor':'bor','bxor':'bxor','shl':'shl','shr':'shr','bnot':'bnot'}[op]

def _num_arith(a, b, fn, int_wrap=False):
    if is_lua_int(a) and is_lua_int(b):
        r = fn(a, b)
        if int_wrap and isinstance(r, int):
            return globals_int_wrap(r)
        return r
    return fn(float(a), float(b))

def globals_int_wrap(x):
    return int_wrap(x)
