def builtin_collectgarbage(interp, args):
    opt = _argn(args, 0, 'collect')
    if opt == 'count':
        return [0.0, 0]
    if opt in ('collect', 'stop', 'restart', 'step'):
        return 0
    if opt == 'isrunning':
        return True
    return 0

def builtin_dofile(interp, args):
    fn = _argn(args, 0)
    if fn is None:
        src_str = sys.stdin.read()
        chunk = '=stdin'
    else:
        with open(fn) as f:
            src_str = f.read()
        chunk = fn
    from lexer import tokenize
    from parser import Parser
    from interpreter import Interpreter, Scope
    from lua_types import LuaFunction
    toks = tokenize(src_str, chunk)
    tree = Parser(toks, chunk).parse_chunk()
    main_fn = LuaFunction([], True, tree, None, chunkname=chunk, line=0)
    outer = Scope(None); outer.set_local('...', [])
    main_fn.env = outer
    try:
        r = interp._call_lua(main_fn, [])
        return r or []
    except ReturnException as r:
        return r.values

def builtin_loadstring(interp, args):
    return builtin_load(interp, args)

def builtin_load(interp, args):
    src = _argn(args, 0)
    if callable(src) or isinstance(src, (LuaFunction, BuiltinFunction)):
        # call to get chunks; concat strings
        chunks = []
        while True:
            r = interp._call_value(src, [])
            if not r or r[0] is None or r[0] == '':
                break
            chunks.append(r[0])
        src = ''.join(chunks)
    chunkname = _argn(args, 1, '=(load)')
    mode = _argn(args, 2)
    env = _argn(args, 3)  # ignored for now
    from lexer import tokenize, LexError
    from parser import Parser, ParseError
    try:
        toks = tokenize(src, chunkname)
        tree = Parser(toks, chunkname).parse_chunk()
    except (LexError, ParseError) as e:
        return [None, f"{chunkname}:{e.line}: {e}"]
    from interpreter import Scope
    main_fn = LuaFunction([], True, tree, None, chunkname=chunkname, line=0)
    outer = Scope(None); outer.set_local('...', [])
    main_fn.env = outer
