            if not line: out.append(None); break
            out.append(line.rstrip('\n'))
        elif fmt == 'L':
            line = self.f.readline()
            if not line: out.append(None); break
            out.append(line)
        elif fmt == 'a':
            out.append(self.f.read())
        elif fmt == 'n':
            data = self.f.read(64).strip()
            out.append(checknum_or_str(data) if data else None)
        elif is_lua_number(fmt):
            n = int(fmt)
            d = self.f.read(n)
            out.append(d if d else None)
        else:
            raise LuaError("bad argument")
    return out

