# Lua pattern matcher (implements most of Lua's string pattern syntax)
# Based on the Lua manual. Returns (start, end, captures) or None.

def _match_class(c, cls):
    """Match a single char against a class character (after %)."""
    if cls == 'a': return c.isalpha()
    if cls == 'A': return not c.isalpha()
    if cls == 'd': return c.isdigit()
    if cls == 'D': return not c.isdigit()
    if cls == 's': return c in ' \t\n\r\f\v'
    if cls == 'S': return c not in ' \t\n\r\f\v'
    if cls == 'w': return c.isalnum()
    if cls == 'W': return not c.isalnum()
    if cls == 'l': return c.islower()
    if cls == 'L': return not c.islower()
    if cls == 'u': return c.isupper()
    if cls == 'U': return not c.isupper()
    if cls == 'p': return not c.isalnum() and not c.isspace() and c not in ' \t\n\r\f\v' and ord(c) >= 0x21 and ord(c) <= 0x7e
    if cls == 'P': return not _match_class(c, 'p')
    if cls == 'c': return ord(c) < 32
    if cls == 'C': return ord(c) >= 32
    if cls == 'x': return c in '0123456789abcdefABCDEF'
    if cls == 'X': return c not in '0123456789abcdefABCDEF'
    return c == cls

def _single_match(c, p, pi):
    """Try to match a single character at s[si] against pattern starting at p[pi].
    Returns length of pattern consumed, or 0 if no match."""
    # Returns (matched: bool, pat_len: int)
    if pi >= len(p): return False, 0
    pc = p[pi]
    if pc == '.':
        return True, 1
    if pc == '%':
        if pi + 1 >= len(p):
            raise ValueError("malformed pattern (ends with '%')")
        return _match_class(c, p[pi+1]), 2
    if pc == '[':
        # find end
        end = pi + 1
        if end < len(p) and p[end] == '^':
            end += 1
        if end < len(p) and p[end] == ']':
            end += 1
        while end < len(p) and p[end] != ']':
            if p[end] == '%' and end+1 < len(p):
                end += 2
            else:
                end += 1
        if end >= len(p):
            raise ValueError("malformed pattern (missing ']')")
        return _match_set(c, p, pi+1, end), end - pi + 1
    # literal char
    return c == pc, 1

def _match_set(c, p, start, end):
    """Match char c against set p[start:end]."""
    neg = False
    i = start
    if i < end and p[i] == '^':
        neg = True
        i += 1
    found = False
    while i < end:
        if p[i] == '%' and i+1 < end:
            if _match_class(c, p[i+1]):
                found = True
            i += 2
        elif i+2 < end and p[i+1] == '-':
            # range
            if p[i] <= c <= p[i+2]:
                found = True
            i += 3
        else:
            if c == p[i]:
                found = True
            i += 1
    return found if not neg else not found

def _pattern_len(p, pi):
    """Length of the single pattern element starting at pi."""
    if pi >= len(p): return 0
    if p[pi] == '%':
        return 2
    if p[pi] == '[':
        end = pi + 1
        if end < len(p) and p[end] == '^': end += 1
        if end < len(p) and p[end] == ']': end += 1
        while end < len(p) and p[end] != ']':
            if p[end] == '%' and end+1 < len(p):
                end += 2
            else:
                end += 1
        return end - pi + 1
    return 1

class _Match:
    def __init__(self, s, p):
        self.s = s
        self.p = p
        self.captures = []  # list of (start, end or -1 for position)

    def match_pat(self, si, pi):
        """Try to match pattern p[pi:] against string s[si:]. Return end si or -1."""
        while pi < len(self.p):
            pc = self.p[pi]
            if pc == '(':
                # start capture
                if pi + 1 < len(self.p) and self.p[pi+1] == ')':
                    # position capture
                    self.captures.append((si, -1))  # position capture
                    r = self.match_pat(si, pi+2)
                    if r < 0:
                        self.captures.pop()
                    return r
                else:
                    self.captures.append((si, -2))  # unclosed
                    r = self.match_pat(si, pi+1)
                    if r < 0:
                        self.captures.pop()
                    return r
            if pc == ')':
                # close capture
                # find last unclosed
                for ci in range(len(self.captures)-1, -1, -1):
                    if self.captures[ci][1] == -2:
                        self.captures[ci] = (self.captures[ci][0], si)
                        r = self.match_pat(si, pi+1)
                        if r < 0:
                            self.captures[ci] = (self.captures[ci][0], -2)
                        return r
                raise ValueError("invalid pattern capture")
            if pc == '$' and pi == len(self.p) - 1:
                return si if si == len(self.s) else -1
            if pc == '%':
                if pi + 1 < len(self.p) and self.p[pi+1].isdigit():
                    n = int(self.p[pi+1])
                    if n < 1 or n > len(self.captures):
                        raise ValueError("invalid capture index")
                    cs, ce = self.captures[n-1]
                    if ce < 0:
                        raise ValueError("invalid capture")
                    cap = self.s[cs:ce]
                    if self.s[si:si+len(cap)] == cap:
                        return self.match_pat(si+len(cap), pi+2)
                    return -1
                # %b (balanced match): %bxy
                if pi + 1 < len(self.p) and self.p[pi+1] == 'b':
                    if pi + 3 >= len(self.p):
                        raise ValueError("malformed %b")
                    open_c = self.p[pi+2]
                    close_c = self.p[pi+3]
                    if si >= len(self.s) or self.s[si] != open_c:
                        return -1
                    depth = 1
                    j = si + 1
                    while j < len(self.s) and depth > 0:
                        if self.s[j] == open_c: depth += 1
                        elif self.s[j] == close_c: depth -= 1
                        j += 1
                    if depth != 0: return -1
                    return self.match_pat(j, pi+4)
            # Regular pattern element
            plen = _pattern_len(self.p, pi)
            next_pi = pi + plen
            quant = self.p[next_pi] if next_pi < len(self.p) else ''
            if quant == '*':
                return self._match_max(si, pi, plen, next_pi + 1, 0)
            if quant == '+':
                return self._match_max(si, pi, plen, next_pi + 1, 1)
            if quant == '-':
                return self._match_min(si, pi, plen, next_pi + 1)
            if quant == '?':
                # try with then without
                if si < len(self.s):
                    m, _ = _single_match(self.s[si], self.p, pi)
                    if m:
                        r = self.match_pat(si + 1, next_pi + 1)
                        if r >= 0: return r
                return self.match_pat(si, next_pi + 1)
            # no quantifier, must match single
            if si >= len(self.s):
                return -1
            m, _ = _single_match(self.s[si], self.p, pi)
            if not m:
                return -1
            si += 1
            pi = next_pi
        return si

    def _match_max(self, si, pi, plen, after_pi, minimum):
        # Greedy: match as many as possible, backtrack
        count = 0
        while si + count < len(self.s):
            m, _ = _single_match(self.s[si + count], self.p, pi)
            if not m: break
            count += 1
        while count >= minimum:
            r = self.match_pat(si + count, after_pi)
            if r >= 0:
                return r
            count -= 1
        return -1

    def _match_min(self, si, pi, plen, after_pi):
        # Lazy: match as few as possible
        while True:
            r = self.match_pat(si, after_pi)
            if r >= 0:
                return r
            if si >= len(self.s):
                return -1
            m, _ = _single_match(self.s[si], self.p, pi)
            if not m:
                return -1
            si += 1

def find_pattern(s, p, init=1, plain=False):
    """Lua-style find. init is 1-based. Returns (start, end, caps) or None."""
    L = len(s)
    if init < 0: init = max(L + init + 1, 1)
    if init == 0: init = 1
    if init > L + 1: return None
    if plain:
        idx = s.find(p, init - 1)
        if idx < 0: return None
        return (idx + 1, idx + len(p), [])
    # anchored?
    anchor = False
    pp = p
    if pp.startswith('^'):
        anchor = True
        pp = pp[1:]
    start = init - 1
    while True:
        m = _Match(s, pp)
        r = m.match_pat(start, 0)
        if r >= 0:
            caps = []
            for cs, ce in m.captures:
                if ce == -1:
                    caps.append(cs + 1)  # position capture (1-based)
                else:
                    caps.append(s[cs:ce])
            return (start + 1, r, caps)
        if anchor:
            return None
        start += 1
        if start > L:
            return None

def match_all(s, p):
    """Generator yielding captures for gmatch."""
    L = len(s)
    start = 0
    anchor = False
    pp = p
    if pp.startswith('^'):
        anchor = True
        pp = pp[1:]
    while start <= L:
        m = _Match(s, pp)
        r = m.match_pat(start, 0)
        if r >= 0:
            caps = []
            for cs, ce in m.captures:
                if ce == -1:
                    caps.append(cs + 1)
                else:
                    caps.append(s[cs:ce])
            if not caps:
                # no captures -> whole match
